// The input guardrail blocked this request, so n8n words the rejection. This map used to be
// GUARDRAIL_REASONS in nodes.py; it moved here with the decision it explains, rather than being
// left in a second place that has to be kept in step with a decision it no longer makes.
const REASONS = {
  keywords: 'it contains phrasing associated with prompt-injection attempts',
  jailbreak: "it looks like an attempt to override the assistant's instructions",
  topicalAlignment: 'it is not a job requisition',
};

// A friendly, on-brand nudge for the common case of someone just saying hi or asking something
// unrelated - deliberately distinct from the terser wording used for keyword and jailbreak
// blocks, since those are adversarial input and should not read as an invitation to try again.
const TOPICAL_ONLY =
  "Hi! I'm the HR Copilot - I screen candidates against job requisitions. Tell me about the " +
  "role you're hiring for (title, required skills, seniority or years of experience) and " +
  "I'll take it from there.";

const triggered = ($json.checks || []).filter(c => c.triggered).map(c => c.name);

let reason;
if (triggered.length === 1 && triggered[0] === 'topicalAlignment') {
  reason = TOPICAL_ONLY;
} else if (triggered.length === 0) {
  // The node routed here, so something failed even if no check named itself.
  reason = 'The request was blocked by the input guardrail.';
} else {
  reason = 'The request was blocked because ' +
    triggered.map(name => REASONS[name] || name).join('; and ') + '.';
}

// Same envelope every terminal branch emits, so the UI has one shape to render.
return [{ json: {
  session_id: $('Screen Webhook').first().json.body.session_id || null,
  guardrail_passed: false,
  rejection_reason: reason,
  shortlist_warning: '',
  requirements: null,
  candidates: [],
  actions: [],
  reply: 'Request rejected: ' + reason,
}}];

// The shortlist relevance check fired, so the action chain below was never entered. This is the
// whole reason the check moved up here: in the version where LangGraph orchestrated, this same
// verdict arrived as a warning printed over interviews that were already booked and invitations
// that had already been sent. Now it is the reason none of that happened.
const agent = $('Screen Agent').first().json;

const WARNING =
  'The shortlist did not match the role you asked for. An automated relevance check thought ' +
  'these candidates come from a different field, so no interviews were booked, no invitations ' +
  'were sent, and nothing was written to the ATS. Please review the screening below.';

return [{ json: {
  session_id: agent.session_id,
  guardrail_passed: true,
  rejection_reason: null,
  shortlist_warning: WARNING,
  requirements: agent.requirements,
  candidates: agent.candidates,
  actions: [],
  reply: '[!] ' + WARNING + '\n\n' + agent.report,
}}];

// Assign an interview slot to every candidate on the shortlist, in one pass.
//
// The whole batch is handled here and the calendar is written exactly once, on purpose.
// Branching per candidate would re-read the calendar before the previous candidate's write
// had landed, so every booking but the last would be silently lost. One read, one write.
//
// The shortlist is read off Screen Agent rather than off $json: the Guardrails node between
// here and there replaces the item with its own verdict, so $json is the check result.
const body = $('Screen Agent').first().json.actions_request;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const calendar = JSON.parse(buffer.toString('utf8'));

const role = body.role || 'Unspecified role';
const candidates = Array.isArray(body.candidates) ? body.candidates : [];

const assignments = [];

for (const candidate of candidates) {
  const name = candidate.candidate_name;

  // Re-running the same requisition must not consume a second slot, so an existing booking
  // for this candidate is reused instead of taking another one.
  let slot = calendar.slots.find(s => s.booked_by === name);
  let status = 'already_scheduled';

  if (!slot) {
    // First fit: the earliest still-free slot in calendar order. Slots claimed earlier in
    // this same loop are already non-null, so the batch never double-books.
    slot = calendar.slots.find(s => s.booked_by === null);
    status = 'scheduled';
  }

  if (!slot) {
    // Nothing free. The candidate still reaches the ATS - only the invitation is withheld,
    // because there is no time to promise them.
    assignments.push({
      ...candidate, role, status: 'no_slots_available',
      slot_id: null, start: null, end: null, interviewer: null,
    });
    continue;
  }

  slot.booked_by = name;
  slot.role = role;

  // One-hour interview: the calendar event needs an end, the JSON slot does not.
  // The trailing 'Z' forces UTC on both the parse and the format, so this is pure wall-clock
  // arithmetic. v1 wrote `new Date(slot.start)` here, which parses as *local* time and then
  // formats as UTC - correct only because the n8n container happens to run in UTC, and off by
  // the host offset anywhere else.
  const startsAt = new Date(slot.start.endsWith('Z') ? slot.start : slot.start + 'Z');

  assignments.push({
    ...candidate,
    role,
    status,
    slot_id: slot.slot_id,
    start: slot.start,
    end: new Date(startsAt.getTime() + 60 * 60 * 1000).toISOString().slice(0, 19),
    interviewer: slot.interviewer,
  });
}

const updated = Buffer.from(JSON.stringify(calendar, null, 2), 'utf8');
return [{
  json: { role, mode: body.mode || 'log', assignments },
  binary: { data: await this.helpers.prepareBinaryData(updated, 'calendar.json', 'application/json') },
}];

// Append one invitation per candidate who actually got a slot, then write the outbox once.
// Candidates with no slot are skipped here by design - an invitation with no time in it is
// worse than no invitation. They are still recorded in the ATS by the next stage.
//
// The candidate list cannot ride here in json: Read Outbox replaces json with file metadata,
// so it is fetched back from the node that produced it.
const assignments = $('Assign Slots').first().json.assignments;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const outbox = JSON.parse(buffer.toString('utf8'));

// Render the slot the way the calendar invitation does, so the two messages a candidate
// receives agree: "Tuesday 8 September 2026, 09:00" rather than a raw ISO timestamp.
// Luxon is only available in n8n expressions, not in Code nodes, hence the plain-JS version.
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
                'September', 'October', 'November', 'December'];

function formatSlot(isoString) {
  const when = new Date(isoString);
  // Fall back to whatever we were given rather than printing "Invalid Date" to a candidate.
  if (isNaN(when.getTime())) return isoString;
  const hours = String(when.getHours()).padStart(2, '0');
  const minutes = String(when.getMinutes()).padStart(2, '0');
  return `${WEEKDAYS[when.getDay()]} ${when.getDate()} ${MONTHS[when.getMonth()]} `
       + `${when.getFullYear()}, ${hours}:${minutes}`;
}

const invitations = [];

for (const a of assignments) {
  // Only a freshly booked slot gets an invitation. 'already_scheduled' means a previous run
  // already sent one for this exact slot - composing another here would be a duplicate email,
  // and in live mode a duplicate real Gmail message and Calendar invite for a time that hasn't
  // changed. Checking status, not just slot_id, is what tells the two cases apart: both carry
  // a slot_id, only 'scheduled' means this execution is the one that claimed it.
  if (a.status !== 'scheduled') continue;

  const start = formatSlot(a.start);
  const invitation = {
    sent_at: new Date().toISOString(),
    to: a.deliver_to || a.candidate_email,
    intended_to: a.candidate_email,
    candidate_name: a.candidate_name,
    role: a.role,
    slot_id: a.slot_id,
    start: a.start,
    interviewer: a.interviewer,
    subject: `Interview invitation - ${a.role}`,
    body: `Hi ${a.candidate_name},\n\nWe reviewed your CV for the ${a.role} position and would like to invite you to an interview on ${start}` +
          (a.interviewer ? ` with ${a.interviewer}` : '') +
          `.\n\nPlease reply to confirm.\n\nBest regards,\nTalent Acquisition`,
  };

  outbox.push(invitation);
  invitations.push(invitation);
}

const updated = Buffer.from(JSON.stringify(outbox, null, 2), 'utf8');
return [{
  json: { invitations, total_sent: outbox.length },
  binary: { data: await this.helpers.prepareBinaryData(updated, 'sent_emails.json', 'application/json') },
}];

// Record every shortlisted candidate, including the ones no slot was free for. Losing a
// candidate from the ATS because the calendar happened to be full would be the worst failure
// mode here - the shortlist is the thing of value, the slot is just logistics.
//
// `notes` is the Evaluator's justification AFTER the graph's grounding guard has had a look at
// it. That guard used to run in the agent's last node, which was one node too late: by then
// this row had already been written with a claim the CV might not support.
const assignments = $('Assign Slots').first().json.assignments;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const ats = JSON.parse(buffer.toString('utf8'));

const entries = [];

for (const a of assignments) {
  const entry = {
    logged_at: new Date().toISOString(),
    candidate_name: a.candidate_name,
    candidate_email: a.candidate_email || null,
    role: a.role,
    status: a.slot_id ? 'interview_scheduled' : 'no_slot_available',
    score: a.score ?? null,
    notes: a.notes || null,
    // v1 could not record this: its ATS call was a separate request that never saw the
    // booking result. Batching the whole sequence into one execution makes it free.
    slot_id: a.slot_id || null,
  };
  ats.push(entry);
  entries.push(entry);
}

const updated = Buffer.from(JSON.stringify(ats, null, 2), 'utf8');
return [{
  json: { entries, total_records: ats.length },
  binary: { data: await this.helpers.prepareBinaryData(updated, 'ats_log.json', 'application/json') },
}];

// Flatten the three stages into one row per action actually performed. Order is per candidate,
// schedule -> invitation -> ATS.
//
// candidate_name is echoed back verbatim, never re-derived: the report lines below are joined to
// candidates by exact string equality, so any casing drift here would silently produce a passing
// candidate with no actions listed beneath them.
const assignSlots = $('Assign Slots').first().json;
const assignments = assignSlots.assignments;
const invitations = $('Compose Invitations').first().json.invitations;
const ats = $('Append ATS Entries').first().json;

// Safe to key by name: retrieval dedupes candidates by name and the evaluator forces
// candidate_name from CV metadata, so one batch cannot contain the same name twice.
const invitationByName = {};
for (const invitation of invitations) invitationByName[invitation.candidate_name] = invitation;

const entryByName = {};
for (const entry of ats.entries) entryByName[entry.candidate_name] = entry;

const results = [];

for (const a of assignments) {
  results.push({
    candidate_name: a.candidate_name,
    action: 'schedule_interview',
    status: a.status,
    details: a.slot_id
      ? {
          slot_id: a.slot_id, start: a.start, end: a.end,
          interviewer: a.interviewer, role: a.role, deliver_to: a.deliver_to || null,
        }
      : { message: 'No free interview slot was available.' },
  });

  // Absent for a candidate with no slot - that absence is the record that nothing was promised.
  const invitation = invitationByName[a.candidate_name];
  if (invitation) {
    results.push({
      candidate_name: a.candidate_name,
      action: 'send_invitation_email',
      status: 'sent',
      details: {
        to: invitation.to, intended_to: invitation.intended_to,
        subject: invitation.subject, slot_id: invitation.slot_id,
      },
    });
  }

  const entry = entryByName[a.candidate_name];
  if (entry) {
    results.push({
      candidate_name: a.candidate_name,
      action: 'log_to_ats',
      status: 'logged',
      details: {
        ats_status: entry.status, score: entry.score, total_records: ats.total_records,
      },
    });
  }
}

return [{
  json: {
    status: 'ok',
    mode: assignSlots.mode,
    role: assignSlots.role,
    candidate_count: assignments.length,
    results,
  },
}];

// The last node before the response, and the only place the two halves of the report meet.
//
// The agent's half covers what the Evaluator decided: who was scored, what they scored, who
// cleared the threshold. It stops there deliberately - at the moment LangGraph rendered it,
// nothing had been booked, and a report that announces an interview before anything booked one
// is exactly the confident-and-wrong output this project keeps designing against.
//
// This half covers what n8n did, which is the only part n8n knows: whether a slot was free and
// whether a message went out.
const agent = $('Screen Agent').first().json;

// Reached on BOTH branches of Has Passing?. When nobody passed, the action chain was never
// entered, so Build Response is an unexecuted node and referencing it throws. That throw is the
// signal that there was nothing to book, so it is caught here rather than paid for with a second
// copy of this envelope on the other branch.
let results = [];
try {
  results = $('Build Response').first().json.results || [];
} catch (error) {
  results = [];
}

// The JS half of what used to be describe_action() in Python. It lives here now because the
// data it formats is produced here.
function detail(row) {
  const d = row.details || {};
  if (row.action === 'schedule_interview' && d.slot_id) {
    return ` (${d.start} with ${d.interviewer || 'TBC'})`;
  }
  if (row.action === 'send_invitation_email' && d.to) return ` (to ${d.to})`;
  if (row.status === 'error') return ` (${d.message || 'no detail'})`;
  return '';
}

const lines = results.map(r => `  - ${r.candidate_name} - ${r.action}: ${r.status}${detail(r)}`);
const reply = lines.length
  ? `${agent.report}\n\nActions taken:\n${lines.join('\n')}`
  : agent.report;

return [{ json: {
  session_id: agent.session_id,
  guardrail_passed: true,
  rejection_reason: null,
  shortlist_warning: '',
  requirements: agent.requirements,
  candidates: agent.candidates,
  actions: results,
  reply,
}}];

// Live mode only: one item per booked candidate. Both Google nodes hang off this node in
// parallel rather than in series, because each reads $json directly - chaining them would
// hand Gmail the Calendar API's event object instead of the invitation.
//
// This runs after the response has already gone back, on both branches of Has Passing?. With
// nobody booked the action chain never ran, so these two references throw - and no bookings
// means there is nothing to send, which is exactly what an empty return produces: the Gmail and
// Calendar nodes receive zero items and do not execute.
let assignments;
let invitations;
try {
  assignments = $('Assign Slots').first().json.assignments;
  invitations = $('Compose Invitations').first().json.invitations;
} catch (error) {
  return [];
}

const byName = {};
for (const invitation of invitations) byName[invitation.candidate_name] = invitation;

return assignments
  // Same rule as Compose Invitations, and for the same reason: 'already_scheduled' candidates
  // already have a real Calendar event and a real Gmail message from whichever run first
  // booked them. Filtering on slot_id alone (true for both statuses) is what caused a re-run
  // of the same requisition to fire a duplicate event and email for an unchanged slot.
  .filter(a => a.status === 'scheduled')
  .map(a => ({
    json: {
      candidate_name: a.candidate_name,
      role: a.role,
      start: a.start,
      end: a.end,
      interviewer: a.interviewer,
      deliver_to: a.deliver_to,
      subject: byName[a.candidate_name].subject,
      message: byName[a.candidate_name].body,
    },
  }));
